/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): 郭銳文 (Raven Kwok) - 189D0 (2016) / Karma Fields - "Sweat" Official MV
 * 原始作品討論 (Original Note): http://xhslink.com/o/A1BUOUA32O9
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。幾何演算法靈感取材自郭銳文先生 189D0
 * 作品中的「四叉樹遞迴剖分與圓-四邊形邊界剪裁求交」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let maxDepth = 6;
let minRectSize;
let timeX = 0, timeY = 0, timeZ = 0;
let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;
let smoothedHigh = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  rectMode(CORNER);
  ellipseMode(CENTER);
  minRectSize = max(width, height) / (2 ** maxDepth);
  colorMode(HSB, 360, 100, 100, 1.0);
};

draw = () => {
  // 1. 動態音訊信號平滑濾波 (Damping Filter)
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.8 : 0.2));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);
  let rawHigh = (typeof high !== 'undefined') ? high : (typeof high_ratio !== 'undefined' ? high_ratio : 0.2);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.12;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.25;
  smoothedMid += (rawMid - smoothedMid) * 0.15;
  smoothedHigh += (rawHigh - smoothedHigh) * 0.2;

  // 2. 時間軸與動態推進
  timeX += 0.002 + smoothedMid * 0.008;
  timeY += 0.003 + smoothedSubBass * 0.01;
  timeZ += 0.005 + smoothedPercussive * 0.02;

  // 3. 背景填色 (高對比度極簡風格)
  background(240, 15, 8);

  // 4. 計算全局幾何焦點 (Focal Center Points)
  let focalX1 = width * 0.5 + sin(timeZ * 1.5) * width * 0.25;
  let focalY1 = height * 0.5 + cos(timeZ * 1.2) * height * 0.25;
  let focalX2 = width * 0.5 + cos(timeX * 2.0) * width * 0.35;
  let focalY2 = height * 0.5 + sin(timeY * 1.8) * height * 0.35;

  let maxSide = max(width, height);
  quadTree(0, 0, maxSide, 0, focalX1, focalY1, focalX2, focalY2);
};

function quadTree(x, y, size, depth, fx1, fy1, fx2, fy2) {
  if (size < minRectSize || depth >= maxDepth) {
    renderLeafNode(x, y, size, depth, fx1, fy1, fx2, fy2);
    return;
  }

  // 根據 Perlin Noise 與音訊特徵判斷是否繼續向下遞迴剖分
  let n = noise((x + timeX * 100) * 0.002, (y + timeY * 100) * 0.002, timeZ);
  let splitThreshold = 0.42 - smoothedSubBass * 0.15 + smoothedPercussive * 0.2;

  if (abs(n - 0.5) > splitThreshold && depth >= 2) {
    renderLeafNode(x, y, size, depth, fx1, fy1, fx2, fy2);
  } else {
    let half = size / 2;
    quadTree(x, y, half, depth + 1, fx1, fy1, fx2, fy2);
    quadTree(x + half, y, half, depth + 1, fx1, fy1, fx2, fy2);
    quadTree(x, y + half, half, depth + 1, fx1, fy1, fx2, fy2);
    quadTree(x + half, y + half, half, depth + 1, fx1, fy1, fx2, fy2);
  }
}

function renderLeafNode(x, y, size, depth, fx1, fy1, fx2, fy2) {
  // 防護：若完全超出畫布範圍則跳過渲染
  if (x > width || y > height || x + size < 0 || y + size < 0) return;

  push();
  let ctx = drawingContext;

  // 使用 HTML5 Canvas 原生剪裁 API 實作「圓與四邊形邊界求交」
  ctx.save();
  ctx.beginPath();
  ctx.rect(x, y, size, size);
  ctx.clip();

  // 1. 葉子節點內部基底背景
  let leafNoise = noise(x * 0.005, y * 0.005, timeZ);
  if (leafNoise > 0.6) {
    fill(0, 0, 95);
  } else if (leafNoise > 0.3) {
    fill(220, 10, 15);
  } else {
    fill(0, 0, 5);
  }
  noStroke();
  rect(x, y, size, size);

  // 2. 幾何圓形與同心弧求交渲染
  let baseRadius = (150 + smoothedSubBass * 350 + sin(timeZ + depth) * 60);
  let rings = 5 + int(smoothedPercussive * 6);
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 210;

  for (let i = rings; i > 0; i--) {
    let r1 = baseRadius * (i / rings);
    let r2 = baseRadius * ((i - 0.5) / rings);

    // 第一焦點同心圓/弧
    let d1 = dist(x + size/2, y + size/2, fx1, fy1);
    if (d1 < r1 + size) {
      if (i % 2 === 0) {
        fill(currentHue, 80, 95, 0.85);
      } else {
        fill(0, 0, 100, 0.9);
      }
      stroke((currentHue + 180) % 360, 60, 20, 0.8);
      strokeWeight(1 + smoothedHigh * 3);
      ellipse(fx1, fy1, r1 * 2, r1 * 2);
    }

    // 第二焦點反色同心圓/弧
    let d2 = dist(x + size/2, y + size/2, fx2, fy2);
    if (d2 < r2 + size) {
      if (i % 2 === 1) {
        fill(0, 0, 0, 0.95);
      } else {
        fill((currentHue + 40) % 360, 85, 90, 0.85);
      }
      stroke(0, 0, 100, 0.6);
      strokeWeight(1.5);
      ellipse(fx2, fy2, r2 * 2, r2 * 2);
    }
  }

  // 3. 節點內部放射狀射線 (Ray Intersections)
  let numRays = 8;
  stroke(0, 0, 100, 0.4);
  strokeWeight(0.75 + smoothedHigh * 2);
  let angleStep = TWO_PI / numRays;
  let rotAngle = timeX * 2.0 + depth * 0.5;

  for (let a = 0; a < TWO_PI; a += (Math.max(0.001, Math.abs(angleStep)) || 1)) {
    let rx = fx1 + cos(a + rotAngle) * baseRadius * 1.5;
    let ry = fy1 + sin(a + rotAngle) * baseRadius * 1.5;
    line(fx1, fy1, rx, ry);
  }

  ctx.restore();
  pop();

  // 4. 葉子節點外框 (Boundary Grid Stroke)
  noFill();
  stroke(0, 0, 100, 0.35 + smoothedSubBass * 0.3);
  strokeWeight(0.8 + depth * 0.2);
  rect(x, y, size, size);
}

